package dev.adamko.kntoolchain.tools.tasks

import dev.adamko.kntoolchain.tools.KnpDatagenPlugin.Companion.ALLOW_UPDATE_PROPERTY
import java.nio.file.Path
import javax.inject.Inject
import kotlin.io.path.*
import org.gradle.api.DefaultTask
import org.gradle.api.file.DirectoryProperty
import org.gradle.api.file.FileSystemOperations
import org.gradle.api.provider.Property
import org.gradle.api.tasks.*
import org.gradle.api.tasks.PathSensitivity.RELATIVE
import org.gradle.work.DisableCachingByDefault
import org.gradle.work.NormalizeLineEndings

/**
 * Sync the code generated by [KnpDataGenTask] into the committed source directory.
 *
 * If the generated code differs from the committed code, the task fails,
 * unless [allowUpdate] is enabled.
 *
 * Motivation: prevent accidentally not committing updates.
 */
@DisableCachingByDefault(because = "Basic file sync")
abstract class KnpDataSyncTask
@Inject
internal constructor(
  private val fs: FileSystemOperations,
) : DefaultTask() {

  /** Generated code, produced by [KnpDataGenTask]. */
  @get:InputDirectory
  @get:PathSensitive(RELATIVE)
  @get:NormalizeLineEndings
  abstract val generatedDataDir: DirectoryProperty

  /** The committed source directory. All existing content will be replaced. */
  @get:OutputDirectory
  abstract val committedDataDir: DirectoryProperty

  /**
   * If `true`, update [committedDataDir] when it differs from [generatedDataDir].
   * Otherwise, fail.
   */
  @get:Input
  abstract val allowUpdate: Property<Boolean>

  init {
    onlyIf("committed data differs from generated data") {
      generateDiff().isNotEmpty()
    }
  }

  @TaskAction
  protected fun action() {
    val committedDataDir = committedDataDir.get().asFile.toPath()
    val allowUpdate = allowUpdate.get()

    val diff = generateDiff()

    if (!allowUpdate) {
      error(
        buildString {
          appendLine("Committed generated code in ${committedDataDir.invariantSeparatorsPathString} is out of date.")
          appendLine("Re-run with -P$ALLOW_UPDATE_PROPERTY=true to update it, then commit the changes.")
          append(diff)
        }
      )
    }

    logger.lifecycle("[$path] updating committed data\n${diff}")

    fs.sync { spec ->
      spec.from(generatedDataDir)
      spec.into(committedDataDir)
    }
  }

  private fun generateDiff(): String {
    val generated = snapshot(generatedDataDir.get().asFile.toPath())
    val committed = snapshot(committedDataDir.get().asFile.toPath())

    val missing = (generated.keys - committed.keys).sorted()
    val unexpected = (committed.keys - generated.keys).sorted()
    val changed = (generated.keys intersect committed.keys).filter { generated[it] != committed[it] }.sorted()

    return buildString {
      fun append(type: String, content: List<String>) {
        if (content.isEmpty()) return
        appendLine("  ${content.size} $type:")
        content.forEach { appendLine("  - $it") }
      }
      append("missing", missing)
      append("unexpected", unexpected)
      append("changed", changed)
    }
  }

  companion object {
    /** Map each file's relative path to its content, with normalised line endings. */
    private fun snapshot(dir: Path): Map<String, String> {
      if (!dir.exists()) return emptyMap()
      return dir.walk()
        .filter { it.isRegularFile() }
        .associate { file ->
          val path = file.relativeTo(dir).invariantSeparatorsPathString
          val content = file.readLines(Charsets.UTF_8).joinToString("\n").trim()
          path to content
        }
    }
  }
}
